<div class="page-actions"><div><p class="mb-0">Catat hasil survey lapangan dan konversi langsung menjadi quotation.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#surveyModal"><i class="bi bi-plus-lg"></i> New Survey</button></div>
<div class="card-panel"><div class="table-responsive"><table class="table align-middle datatable"><thead><tr><th>Survey</th><th>Customer</th><th>Request</th><th>Date</th><th>Surveyor</th><th>Findings</th><th>Action</th></tr></thead><tbody><?php foreach($surveys as $s): ?><tr><td><strong><?= e($s['survey_number']) ?></strong></td><td><?= e($s['customer_name']) ?></td><td><?= e($s['request_number']??'-') ?></td><td><?= e($s['survey_date']) ?></td><td><?= e($s['surveyor_name']??'-') ?></td><td><?= e(mb_strimwidth((string)$s['findings'],0,70,'…')) ?></td><td><button class="btn btn-sm btn-outline-primary ajax-action" data-url="<?= url('/surveys/'.$s['id'].'/convert') ?>">Create Quotation</button> <button class="btn btn-sm btn-light collab-btn" data-entity="survey" data-id="<?= $s['id'] ?>"><i class="bi bi-paperclip"></i></button></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="surveyModal"><div class="modal-dialog modal-lg"><form class="modal-content ajax-form" method="post" action="<?= url('/surveys') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Site Survey</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Service Request</label><select class="form-select" name="service_request_id"><option value="">Optional</option><?php foreach($requests as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['request_number']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Survey Date</label><input type="date" class="form-control" name="survey_date" value="<?= date('Y-m-d') ?>"></div><div class="col-md-6"><label class="form-label">Surveyor</label><select class="form-select" name="surveyor_id"><?php foreach($users as $u): ?><option value="<?= $u['id'] ?>" <?= $u['id']==\App\Core\Auth::id()?'selected':'' ?>><?= e($u['name']) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Findings</label><textarea class="form-control" name="findings" rows="3"></textarea></div><div class="col-12"><label class="form-label">Recommended Solution</label><textarea class="form-control" name="recommended_solution" rows="3"></textarea></div><div class="col-md-8"><label class="form-label">Estimated Materials</label><textarea class="form-control" name="estimated_materials" rows="2"></textarea></div><div class="col-md-4"><label class="form-label">Estimated Labor</label><input class="form-control" type="number" step="0.01" name="estimated_labor"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes"></textarea></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save Survey</button></div></form></div></div>
